const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
const tabs=[...document.querySelectorAll('[data-dojo]')],filter=document.querySelector('#course-filter');let dojo='A';
function renderSchedule(){const d=CSAB_DOJOS.find(x=>x.id===dojo);document.querySelector('#dojo-title').textContent='Dojo '+d.id+' — '+d.name;document.querySelector('#dojo-place').textContent=d.place+' · '+d.surface;const rows=d.rows.filter(r=>filter.value==='Tous'||(filter.value==='Baby'?r[1].includes('Baby'):filter.value==='Taïso'?r[1].includes('Taïso'):!r[1].includes('Baby')&&!r[1].includes('Taïso')));const body=document.querySelector('#schedule-rows');body.replaceChildren();for(const row of rows){const tr=document.createElement('tr');row.forEach(text=>{const td=document.createElement('td');td.textContent=text;tr.append(td)});body.append(tr)}document.querySelector('#no-courses').hidden=rows.length>0;document.querySelector('.table-scroll').hidden=!rows.length;tabs.forEach(t=>{const selected=t.dataset.dojo===dojo;t.setAttribute('aria-selected',selected);t.tabIndex=selected?0:-1});document.querySelector('#planning').setAttribute('aria-labelledby','tab-'+dojo);}
tabs.forEach((b,i)=>{b.onclick=()=>{dojo=b.dataset.dojo;renderSchedule()};b.onkeydown=e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();tabs[next].focus();tabs[next].click()}}});filter.onchange=renderSchedule;renderSchedule();
document.querySelectorAll('[data-course]').forEach(b=>b.onclick=()=>{filter.value=b.dataset.course;dojo='A';renderSchedule();document.querySelector('#horaires').scrollIntoView({behavior:reduce?'instant':'smooth'});});
document.querySelectorAll('[data-price]').forEach(b=>b.onclick=()=>{const renewal=b.dataset.price==='renew';document.querySelectorAll('[data-price]').forEach(t=>t.setAttribute('aria-pressed',t===b));document.querySelector('#baby-price').textContent=renewal?'285':'320';document.querySelector('#baby-detail').textContent=renewal?'Renouvellement de l’adhésion':'Pack adhérent inclus';document.querySelector('#judo-price').textContent=renewal?'335':'370';document.querySelector('#judo-detail').textContent=renewal?'1re inscription du foyer · Renouvellement':'1re inscription du foyer · Pack adhérent inclus';document.querySelector('#family-price').textContent=renewal?'2e : 325 € · 3e : 310 €':'2e : 355 € · 3e : 340 €';});
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('.header nav');menu.onclick=()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Fermer le menu':'Ouvrir le menu');nav.classList.toggle('open',open);menu.textContent=open?'×':'☰';};nav.querySelectorAll('a').forEach(a=>a.onclick=()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='☰';});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){menu.click();menu.focus()}});
if(!reduce){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.section-head,.club-copy,.course-card,.price-grid article,.action-list article').forEach(el=>{el.classList.add('reveal');observer.observe(el)});document.querySelectorAll('.tilt-card').forEach(card=>{card.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse')return;const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;card.style.transform=`perspective(1000px) rotateX(${-y*5}deg) rotateY(${x*6}deg) translateY(-3px)`;});card.addEventListener('pointerleave',()=>card.style.transform='');});}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'show_class_schedule',title:'Afficher les horaires du CSAB',description:'Sélectionne un dojo et une discipline dans le planning visible, puis renvoie les créneaux de la saison 2026–2027. Ne réserve pas de cours.',inputSchema:{type:'object',properties:{dojo:{type:'string',enum:['A','B','D']},discipline:{type:'string',enum:['Tous','Baby','Judo','Taïso']}},required:['dojo','discipline'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!['A','B','D'].includes(input.dojo)||!['Tous','Baby','Judo','Taïso'].includes(input.discipline))throw new Error('Choisis un dojo A, B ou D et une discipline valide.');dojo=input.dojo;filter.value=input.discipline;renderSchedule();const rows=[...document.querySelector('#schedule-rows').children].map(r=>[...r.children].map(c=>c.textContent));return{dojo,discipline:filter.value,saison:'2026–2027',rows};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
